css:
.prices {
  margin: 24px;
  border-collapse: collapse;
  font-family: system-ui, sans-serif;
  font-size: 20px;
}

.prices th,
.prices td {
  padding: 8px 16px;
  border-bottom: 1px solid #e4e4e7;
  text-align: start;
}

.prices th {
  font-size: 13px;
  color: #71717a;
}

.prices .num {
  text-align: end;
}

.proportional {
  font-variant-numeric: proportional-nums;
}

.tabular {
  font-variant-numeric: tabular-nums;
}

.total {
  font-weight: 700;
}
